/* On this page: highlight the heading in view. More from Rechtien: leave this post out and show three. */
(function () {
  var links = [].slice.call(document.querySelectorAll('[data-bz-node="p-toc"] a[href^="#"]'));
  var targets = links.map(function (a) { return document.getElementById(a.getAttribute('href').slice(1)); }).filter(Boolean);
  if (links.length && 'IntersectionObserver' in window) {
    var map = {};
    links.forEach(function (a) { map[a.getAttribute('href').slice(1)] = a; });
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        if (en.isIntersecting && map[en.target.id]) {
          links.forEach(function (l) { l.classList.remove('is-active'); });
          map[en.target.id].classList.add('is-active');
        }
      });
    }, { rootMargin: '-10% 0px -75% 0px' });
    targets.forEach(function (t) { io.observe(t); });
  }
  var here = location.pathname.replace(/\/$/, '');
  var cards = [].slice.call(document.querySelectorAll('[data-bz-node="p-more"] a.bz-card'));
  var kept = 0;
  cards.forEach(function (a) {
    if (a.getAttribute('href').replace(/\/$/, '') === here || kept >= 3) a.parentNode.removeChild(a);
    else kept++;
  });
})();
